Q = {
"24:1": "«سورة انزلناها وفرضناها» چرا یک سوره «فرض» خوانده می‌شود، نه یک حکم؟ و «فرضناها» به الزام همهٔ احکام این سوره است یا به قطعیت و تقدیر آنها؟",
"24:2": "«ولا تأخذکم بهما رأفة فی دین الله» رأفت مانع اجرا است یا مانع شدت؟ و «ولیشهد عذابهما طائفة» اجرای علنی حد را بر چه حکمتی استوار می‌کند؟",
"24:3": "«الزانی لا ینکح الا زانیة او مشرکة» حکم تحریم است، خبر از غالب، یا نکوهش؟ و «وحرم ذلک علی المؤمنین» به چه چیزی بازمی‌گردد؟",
"24:4": "«ثم لم یأتوا باربعة شهداء فاجلدوهم ثمانین جلدة» چرا قذف را با چهار شاهد می‌سنجد و عدم اقامهٔ شهود را مجازات می‌کند؟ و «ولا تقبلوا لهم شهادة ابداً» تا کجا جاری است؟",
"24:5": "«الا الذین تابوا» استثنا به کدام جمله‌ها برمی‌گردد: فسق، رد شهادت، یا حد؟ و توبهٔ قاذف چگونه ثابت می‌شود؟",
"24:6": "«والذین یرمون ازواجهم ولم یکن لهم شهداء الا انفسهم» «انفسهم» استثنای شهود است یا شهادت خودشان؟ و چرا برای همسر سازوکاری جدا (لعان) آمده است؟",
"24:7": "«والخامسة ان لعنت الله علیه ان کان من الکاذبین» چرا شهادت پنجم با لعن است و آیا لعان یک قسم است یا شهادت؟",
"24:8": "«ویدرؤا عنها العذاب ان تشهد اربع شهادات» «العذاب» حد زنا است یا عذاب اخروی؟ و چرا مرد در لعان سرپیچی کند حد قذف بر او است و زن اگر سرپیچی کند چه؟",
"24:9": "«والخامسة ان غضب الله علیها» چرا برای زن «غضب» و برای مرد «لعنت» آمده است؟ و آیا این تفاوت نشان از تفاوتی در جرم است؟",
"24:10": "«ولولا فضل الله علیکم ورحمته وان الله تواب حکیم» جواب «لولا» چرا حذف شده و حذف چه می‌گوید؟ «تواب حکیم» با لعان چه رابطه‌ای دارد؟",
"24:11": "«ان الذین جاءوا بالافک عصبة منکم» «عصبة» چند نفر و چه کسانی‌اند؟ و «لا تحسبوه شراً لکم بل هو خیر لکم» چگونه تهمتی دردناک خیر می‌شود؟ و «الذی تولی کبره» چه کسی است؟",
"24:12": "«ظن المؤمنون والمؤمنات بانفسهم خیراً» چرا به‌جای «بهم» «بانفسهم» آمده است؟ و این تعبیر چه اصل اخلاقی را می‌رساند؟",
"24:13": "«لولا جاؤوا علیه باربعة شهداء» این معیار را چگونه با قاعدهٔ «قاذف باید چهار شاهد بیاورد» می‌سنجد، و «عند الله هم الکاذبون» حکمی قضایی است یا اخروی؟",
"24:14": "«ولولا فضل الله علیکم ورحمته فی الدنیا والآخرة لمسکم فی ما افضتم فیه عذاب عظیم» «افضتم» چه نوع سخن‌گستری را می‌گوید و عذاب چرا نیامد؟",
"24:15": "«اذ تلقونه بالسنتکم وتقولون بافواهکم ما لیس لکم به علم» چرا «بألسنتکم» و «بأفواهکم» هر دو می‌آیند؟ و «تحسبونه هیناً وهو عند الله عظیم» چه معیاری برای گناه گفتار می‌دهد؟",
"24:16": "«ما یکون لنا ان نتکلم بهذا سبحانک» تسبیح در برابر تهمت چه می‌گوید؟ و واکنش مطلوب در برابر شایعه با چه الگوی ادبی بیان شده است؟",
"24:17": "«یعظکم الله ان تعودوا لمثله ابداً» «ابداً» چه می‌گوید؟ و شرط «ان کنتم مؤمنین» ایمان را به چه چیزی گره می‌زند؟",
"24:18": "«ویبین الله لکم الآیات» «آیات» در این آیه همان آیات تشریعی است یا عبرت‌های قصه؟ و آیا «علیم حکیم» توضیح آن است؟",
"24:19": "«ان الذین یحبون ان تشیع الفاحشة فی الذین آمنوا» آیا صرف «دوست داشتن» شیوع فاحشه گناه است، و «عذاب الیم فی الدنیا» به چه حد یا کیفری اشاره دارد؟",
"24:20": "تکرار «ولولا فضل الله علیکم ورحمته» در آیه‌های ۱۰، ۱۴، ۲۰ چه الگوی بلاغی می‌سازد؟ و «رؤوف رحیم» نسبت به دو بار پیشین چه افزوده دارد؟",
"24:21": "«لا تتبعوا خطوات الشیطان» «خطوات» تدریج را می‌رساند؛ چگونه شیطان با گام‌های کوچک به «فحشاء و منکر» می‌رسد؟ و «ما زکی منکم من احد ابدا» چه می‌گوید؟",
"24:22": "«ولا یأتل اولوا الفضل منکم والسعة» آیه دربارهٔ چه کسی و چه سوگندی است؟ و «الا تحبون ان یغفر الله لکم» عفو انسانی را چگونه مقدمهٔ عفو الهی می‌کند؟",
"24:23": "«ان الذین یرمون المحصنات الغافلات المؤمنات لعنوا فی الدنیا والآخرة» «الغافلات» چه قیدی است؟ و آیا لعن دنیوی شامل هر قاذفی است یا قاذفِ به‌ویژه زنان پیامبر؟",
"24:24": "«یوم تشهد علیهم السنتهم وایدیهم وارجلهم» شهادت اعضا چه ارتباطی با «الافک» دارد و چرا زبان اولین عضو است؟",
"24:25": "«یوفیهم الله دینهم الحق» «دین» به چه معناست: جزا یا آیین؟ و «ویعلمون ان الله هو الحق المبین» چه می‌گوید؟",
"24:26": "«الخبیثات للخبیثین... والطیبات للطیبین» این آیه حکم کلی یا تبرئهٔ مشخص است؟ و «اولئک مبرؤون مما یقولون» به چه کسانی بازمی‌گردد؟",
"24:27": "«لا تدخلوا بیوتاً غیر بیوتکم حتی تستأنسوا وتسلموا علی اهلها» «تستأنسوا» چه معنایی دارد: اجازه گرفتن، آگاه ساختن، یا انس گرفتن؟ و ترتیب سلام و استیذان چیست؟",
"24:28": "«فان لم تجدوا فیها احداً فلا تدخلوها حتی یؤذن لکم» اگر کسی در خانه نباشد چرا ورود حرام است؟ و «وان قیل لکم ارجعوا فارجعوا هو ازکی لکم» چه حدی برای حریم می‌گذارد؟",
"24:29": "«لیس علیکم جناح ان تدخلوا بیوتاً غیر مسکونة فیها متاع لکم» «غیر مسکونة» چه جاهایی را شامل می‌شود و استثنا بر چه قاعده‌ای است؟",
"24:30": "«قل للمؤمنین یغضوا من ابصارهم» «من» تبعیضیه است یا بیانیه؟ و پیوند غض بصر با حفظ فرج چه نسبتی را می‌رساند؟",
"24:31": "«الا ما ظهر منها» و «ولیضربن بخمرهن علی جیوبهن» چه مرزی برای زینت و پوشش تعیین می‌کند؟ آیا «ما ظهر» کیفیتی تاریخی-عرفی دارد یا ثابت است؟",
"24:32": "«وانکحوا الایامی منکم والصالحین من عبادکم وامائکم» مخاطب امر چه کسانی‌اند: اولیا یا جامعه؟ و وعدهٔ «یغنهم الله من فضله» با فقر چه رابطه‌ای دارد؟",
"24:33": "«ولیستعفف الذین لا یجدون نکاحاً» و «فکاتبوهم ان علمتم فیهم خیراً» حکم مکاتبه واجب است یا مستحب؟ و «ولا تکرهوا فتیاتکم علی البغاء» چه واقعیتی را در نظر دارد؟",
"24:34": "«آیات مبینات ومثلاً من الذین خلوا من قبلکم وموعظة للمتقین» «مثل» اشاره به چه قصه‌هایی است؟ و چرا موعظه ویژهٔ متقین است؟",
"24:35": "«الله نور السماوات والارض» «نور» به چه معنا است: منور، هادی، یا ظاهر؟ و تمثیل «مشکاة... مصباح... زجاجة... شجرة مبارکة زیتونة» چه می‌گوید؟ «نور علی نور» چیست؟",
"24:36": "«فی بیوت اذن الله ان ترفع» «بیوت» مساجدند، خانهٔ پیامبر و اهل او، یا هر خانهٔ عبادت؟ و «ترفع» رفع معنوی است یا مادی؟",
"24:37": "«رجال لا تلهیهم تجارة ولا بیع عن ذکر الله» چرا «رجال» و آیا تعبیر مخصوص مردان است؟ و «یوماً تتقلب فیه القلوب والابصار» چه تصویری است؟",
"24:38": "«لیجزیهم الله احسن ما عملوا» «احسن» به چه معناست: بهترین عمل یا بهترین پاداش؟ و «بغیر حساب» چه می‌گوید؟",
"24:39": "«والذین کفروا اعمالهم کسراب بقیعة» تشبیه به سراب چه نکته‌ای دربارهٔ اعمال کافران دارد؟ و «ووجد الله عنده فوفاه حسابه» چه شگفتی را می‌گوید؟",
"24:40": "«او کظلمات فی بحر لجی» «او» تردید است یا تنوع؟ و تصویر امواج و ابر و ظلمات لایه‌لایه چه نسبتی با دانش دریانوردی دارد؟ و «ومن لم یجعل الله له نوراً فما له من نور» چه تقابلی با آیهٔ ۳۵ می‌سازد؟",
"24:41": "«الم تر ان الله یسبح له من فی السماوات والارض والطیر صافات» تسبیح موجودات حقیقی است یا حالی؟ و «قد علم صلاته وتسبیحه» ضمیر به چه چیزی برمی‌گردد؟",
"24:42": "«ولله ملک السماوات والارض والی الله المصیر» چرا این جملهٔ کوتاه پس از آیهٔ تسبیح می‌آید؟ و چه نسبتی با «المصیر» در پایان بخش دارد؟",
"24:43": "«یزجی سحاباً ثم یؤلف بینه ثم یجعله رکاماً» توصیف مراحل ابر را چگونه با پدیده‌شناسی بارش می‌سنجد؟ و «یصیب به من یشاء» با قانون‌مندی سازگار است؟",
"24:44": "«یقلب الله اللیل والنهار» «تقلیب» چه تصویری است و «لعبرة لاولی الابصار» به کدام نوع بصیرت دلالت دارد؟",
"24:45": "«والله خلق کل دابة من ماء» «ماء» آب است یا نطفه؟ و تقسیم به خزنده، دوپا و چهارپا چه نوع استدلالی است؟ «یخلق الله ما یشاء» چه می‌گوید؟",
"24:46": "«لقد انزلنا آیات مبینات والله یهدی من یشاء الی صراط مستقیم» هدایت‌دادن «من یشاء» را چگونه با «آیات مبینات» آشکار کنار هم می‌گذارد؟",
"24:47": "«ویقولون آمنا بالله وبالرسول واطعنا ثم یتولی فریق منهم» «فریق» چه کسانی‌اند و «وما اولئک بالمؤمنین» ایمان را به چه معیاری حواله می‌دهد؟",
"24:48": "«واذا دعوا الی الله ورسوله لیحکم بینهم اذا فریق منهم معرضون» «یحکم» ضمیر به رسول یا خدا؟ و حکم پیامبر را چگونه همان حکم خدا می‌داند؟",
"24:49": "«وان یکن لهم الحق یأتوا الیه مذعنین» دربارهٔ رفتار دوگانهٔ منافقان در قضاوت چه می‌گوید و «مذعنین» با چه روحیه‌ای است؟",
"24:50": "«افی قلوبهم مرض ام ارتابوا ام یخافون ان یحیف الله علیهم ورسوله» سه فرض چه تفاوتی دارند و جواب «بل اولئک هم الظالمون» کدام را پذیرفت؟",
"24:51": "«انما کان قول المؤمنین اذا دعوا... ان یقولوا سمعنا واطعنا» «سمعنا واطعنا» را چگونه با «سمعنا وعصینا» (۲:۹۳) می‌سنجد و آیا مراد پذیرش بی‌چون‌وچرا است؟",
"24:52": "«ومن یطع الله ورسوله ویخش الله ویتقه فاولئک هم الفائزون» تفاوت «خشیة» و «تقوی» چیست و چرا «فائزون» با این سه شرط می‌آید؟",
"24:53": "«واقسموا بالله جهد ایمانهم لئن امرتهم لیخرجن» این قسم دربارهٔ چه خروجی است: جنگ، یا هجرت؟ و «طاعة معروفة» به چه معناست؟",
"24:54": "«قل اطیعوا الله واطیعوا الرسول» تکرار فعل «اطیعوا» چه معنایی دارد و «فانما علیه ما حمل وعلیکم ما حملتم» مسئولیت‌ها را چگونه تقسیم می‌کند؟",
"24:55": "«وعد الله الذین آمنوا منکم وعملوا الصالحات لیستخلفنهم فی الارض» «منکم» مخاطب چه کسانی‌اند: صحابه، اهل بیت، یا همهٔ مؤمنان؟ و «استخلاف» تحقق تاریخی دارد یا آینده؟",
"24:56": "«واقیموا الصلاة وآتوا الزکاة واطیعوا الرسول لعلکم ترحمون» چرا پس از وعدهٔ استخلاف فرمان به نماز و زکات و اطاعت می‌آید؟ و رابطهٔ «ترحمون» با استخلاف چیست؟",
"24:57": "«لا تحسبن الذین کفروا معجزین فی الارض» «معجزین» به چه معنا است؟ و چرا پس از وعدهٔ مؤمنان بلافاصله تهدید کافران می‌آید؟",
"24:58": "«لیستأذنکم الذین ملکت ایمانکم والذین لم یبلغوا الحلم منکم ثلاث مرات» سه زمان ذکرشده چرا «عورات» خوانده می‌شوند؟ و آیا حکم واجب است یا استحبابی و آیا منسوخ شده است؟",
"24:59": "«واذا بلغ الاطفال منکم الحلم فلیستأذنوا کما استأذن الذین من قبلهم» «الذین من قبلهم» چه کسانی‌اند و چرا بلوغ مرز بین دو حکم است؟",
"24:60": "«والقواعد من النساء اللاتی لا یرجون نکاحاً» «القواعد» چه کسانی‌اند و «یضعن ثیابهن» به چه معنا است؟ و «وان یستعففن خیر لهن» چه می‌گوید؟",
"24:61": "«لیس علی الاعمی حرج ولا علی الاعرج حرج ولا علی المریض حرج» این حرج‌زدایی با «ان تأکلوا من بیوتکم» چه رابطه‌ای دارد و «او ما ملکتم مفاتحه» به چه معناست؟",
"24:62": "«انما المؤمنون الذین آمنوا بالله ورسوله واذا کانوا معه علی امر جامع» «امر جامع» چیست و چرا ترک مجلس بدون اذن نشانهٔ ضعف ایمان است؟",
"24:63": "«لا تجعلوا دعاء الرسول بینکم کدعاء بعضکم بعضاً» «دعاء الرسول» دعا کردن او است یا فراخواندن او؟ و «یتسللون منکم لواذاً» چه می‌گوید؟",
"24:64": "«الا ان لله ما فی السماوات والارض قد یعلم ما انتم علیه» «قد یعلم» با «قد» چه معنایی دارد و چرا سوره با علم الهی به رفتار و حساب قیامت پایان می‌یابد؟",
}
